import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import LAND_DOTS from "./landDots.json";

/* Country centroids for the names placeFromTimezone() returns. Visitors only
   report a timezone, so a country dot is as precise as this can honestly be. */
export const COUNTRY_COORDS = {
  "United States": [39.8, -98.6],
  Canada: [56.1, -106.3],
  Mexico: [23.6, -102.5],
  Colombia: [4.6, -74.1],
  Peru: [-9.2, -75.0],
  Brazil: [-14.2, -51.9],
  Argentina: [-38.4, -63.6],
  Chile: [-35.7, -71.5],
  "United Kingdom": [54.0, -2.0],
  Ireland: [53.4, -8.2],
  Portugal: [39.4, -8.2],
  Spain: [40.5, -3.7],
  France: [46.2, 2.2],
  Belgium: [50.5, 4.5],
  Netherlands: [52.1, 5.3],
  Germany: [51.2, 10.5],
  Switzerland: [46.8, 8.2],
  Austria: [47.5, 14.6],
  Italy: [41.9, 12.6],
  Czechia: [49.8, 15.5],
  Poland: [51.9, 19.1],
  Hungary: [47.2, 19.5],
  Romania: [45.9, 25.0],
  Greece: [39.1, 21.8],
  Sweden: [60.1, 18.6],
  Norway: [60.5, 8.5],
  Denmark: [56.3, 9.5],
  Finland: [61.9, 25.7],
  Ukraine: [48.4, 31.2],
  Russia: [55.8, 37.6],
  Turkey: [39.0, 35.2],
  Israel: [31.0, 34.9],
  UAE: [23.4, 53.8],
  "Saudi Arabia": [23.9, 45.1],
  Qatar: [25.4, 51.2],
  Pakistan: [30.4, 69.3],
  India: [21.0, 78.9],
  "Sri Lanka": [7.9, 80.8],
  Bangladesh: [23.7, 90.4],
  Nepal: [28.4, 84.1],
  Thailand: [15.9, 100.9],
  Vietnam: [14.1, 108.3],
  Indonesia: [-2.5, 118.0],
  Singapore: [1.35, 103.8],
  Malaysia: [4.2, 102.0],
  Philippines: [12.9, 121.8],
  "Hong Kong": [22.3, 114.2],
  Taiwan: [23.7, 121.0],
  China: [35.9, 104.2],
  "South Korea": [35.9, 127.8],
  Japan: [36.2, 138.3],
  Australia: [-25.3, 133.8],
  "New Zealand": [-40.9, 174.9],
  Egypt: [26.8, 30.8],
  Nigeria: [9.1, 8.7],
  Kenya: [-0.02, 37.9],
  "South Africa": [-30.6, 22.9],
};

const HOME = COUNTRY_COORDS.India;
const R = 1;
const DEG = Math.PI / 180;

const toVec = (lat, lng, r = R) => {
  const phi = (90 - lat) * DEG;
  const theta = (lng + 180) * DEG;
  return new THREE.Vector3(
    -r * Math.sin(phi) * Math.cos(theta),
    r * Math.cos(phi),
    r * Math.sin(phi) * Math.sin(theta)
  );
};

/** Group rotation that brings (lat, lng) to face the camera. */
const facing = (lat, lng) => {
  const v = toVec(lat, lng);
  return { y: -Math.atan2(v.x, v.z), x: lat * DEG * 0.6 };
};

const THEMES = {
  dark: {
    land: new THREE.Color("#7c8aa5"),
    landAlpha: 0.55,
    sphere: new THREE.Color("#1d2230"),
    atmosphere: new THREE.Color("#3987e5"),
    marker: new THREE.Color("#5aa2ff"),
    arc: new THREE.Color("#8fc1ff"),
  },
  light: {
    land: new THREE.Color("#8a8f9c"),
    landAlpha: 0.6,
    sphere: new THREE.Color("#f3e9e1"),
    atmosphere: new THREE.Color("#2a78d6"),
    marker: new THREE.Color("#2a78d6"),
    arc: new THREE.Color("#2a78d6"),
  },
};

const dotMaterial = (color, alpha) =>
  new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: {
      uColor: { value: color },
      uAlpha: { value: alpha },
      uSize: { value: 1 },
    },
    vertexShader: `
      uniform float uSize;
      varying float vFacing;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        // fade dots toward the limb so the sphere reads as round
        vec3 n = normalize(normalMatrix * normalize(position));
        vFacing = clamp(n.z, 0.0, 1.0);
        gl_PointSize = uSize * (0.6 + vFacing * 0.9);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform float uAlpha;
      varying float vFacing;
      void main() {
        vec2 c = gl_PointCoord - 0.5;
        if (dot(c, c) > 0.25) discard;
        gl_FragColor = vec4(uColor, uAlpha * (0.25 + vFacing * 0.75));
      }
    `,
  });

// Glow behind the sphere — a fresnel rim on a slightly larger back-face shell
const atmosphereMaterial = (color) =>
  new THREE.ShaderMaterial({
    transparent: true,
    side: THREE.BackSide,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: { uColor: { value: color } },
    vertexShader: `
      varying vec3 vNormal;
      void main() {
        vNormal = normalize(normalMatrix * normal);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      varying vec3 vNormal;
      void main() {
        float i = pow(0.62 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 4.0);
        gl_FragColor = vec4(uColor, 1.0) * clamp(i, 0.0, 1.0) * 0.9;
      }
    `,
  });

// Arc with a travelling comet of light along it
const arcMaterial = (color, offset) =>
  new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: {
      uColor: { value: color },
      uTime: { value: 0 },
      uOffset: { value: offset },
    },
    vertexShader: `
      attribute float t;
      varying float vT;
      void main() {
        vT = t;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform float uTime;
      uniform float uOffset;
      varying float vT;
      void main() {
        float head = fract(uTime * 0.28 + uOffset) * 1.6 - 0.3;
        float d = head - vT;
        float comet = d > 0.0 ? exp(-d * 9.0) : 0.0;
        float base = 0.12;
        gl_FragColor = vec4(uColor, base + comet * 0.95);
      }
    `,
  });

const buildArc = (from, to) => {
  const a = toVec(from[0], from[1]);
  const b = toVec(to[0], to[1]);
  const dist = a.distanceTo(b);
  const mid = a
    .clone()
    .add(b)
    .multiplyScalar(0.5)
    .normalize()
    .multiplyScalar(R + 0.15 + dist * 0.28);
  const curve = new THREE.QuadraticBezierCurve3(a, mid, b);
  const pts = curve.getPoints(64);
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  geo.setAttribute(
    "t",
    new THREE.Float32BufferAttribute(
      pts.map((_, i) => i / (pts.length - 1)),
      1
    )
  );
  return geo;
};

/**
 * Interactive dotted globe. Drag to spin (with inertia), idles into a slow
 * auto-rotate, hover a marker for its count, and `focus` swings the globe
 * to a country. Arcs run from every visitor country to home (India).
 */
const Globe = ({ places, mode = "dark", focus, onHover }) => {
  const mountRef = useRef(null);
  const apiRef = useRef({});
  const [tip, setTip] = useState(null);

  // Scene: built once per theme
  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return undefined;
    const theme = THEMES[mode] || THEMES.dark;
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)")
      .matches;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    renderer.setPixelRatio(dpr);
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(35, 1, 0.1, 100);
    camera.position.set(0, 0, 3.35);

    const globe = new THREE.Group();
    scene.add(globe);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(R * 0.995, 64, 64),
      new THREE.MeshBasicMaterial({ color: theme.sphere })
    );
    globe.add(sphere);

    const atmosphere = new THREE.Mesh(
      new THREE.SphereGeometry(R * 1.12, 64, 64),
      atmosphereMaterial(theme.atmosphere)
    );
    scene.add(atmosphere);

    const landGeo = new THREE.BufferGeometry().setFromPoints(
      LAND_DOTS.map(([lat, lng]) => toVec(lat, lng, R * 1.002))
    );
    const landMat = dotMaterial(theme.land, theme.landAlpha);
    landMat.uniforms.uSize.value = 2.6 * dpr;
    globe.add(new THREE.Points(landGeo, landMat));

    const markers = new THREE.Group();
    const arcs = new THREE.Group();
    globe.add(markers, arcs);

    const start = facing(HOME[0], HOME[1]);
    const state = {
      rotY: start.y,
      rotX: start.x,
      velY: 0,
      targetY: null,
      targetX: null,
      dragging: false,
      lastX: 0,
      lastY: 0,
      idleAt: 0,
      visible: true,
      markerData: [],
      pointer: null,
    };

    const resize = () => {
      const { width, height } = mount.getBoundingClientRect();
      if (!width || !height) return;
      renderer.setSize(width, height, false);
      renderer.domElement.style.width = `${width}px`;
      renderer.domElement.style.height = `${height}px`;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };
    resize();
    let resizeFrame = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(resize);
    });
    ro.observe(mount);

    const io = new IntersectionObserver(([entry]) => {
      state.visible = entry.isIntersecting;
    });
    io.observe(mount);

    /* ---- pointer: drag to spin, hover to inspect ---- */
    const el = renderer.domElement;
    const onDown = (e) => {
      state.dragging = true;
      state.targetY = state.targetX = null;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      el.setPointerCapture?.(e.pointerId);
    };
    const onMove = (e) => {
      const rect = el.getBoundingClientRect();
      state.pointer = { x: e.clientX - rect.left, y: e.clientY - rect.top };
      if (!state.dragging) return;
      const dx = e.clientX - state.lastX;
      const dy = e.clientY - state.lastY;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      state.velY = dx * 0.005;
      state.rotY += dx * 0.005;
      state.rotX = Math.max(-1, Math.min(1, state.rotX + dy * 0.004));
      state.idleAt = performance.now();
    };
    const onUp = () => {
      state.dragging = false;
      state.idleAt = performance.now();
    };
    const onLeave = () => {
      state.pointer = null;
    };
    el.addEventListener("pointerdown", onDown);
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerup", onUp);
    el.addEventListener("pointercancel", onUp);
    el.addEventListener("pointerleave", onLeave);

    /* ---- data layer, rebuilt when places change ---- */
    const setPlaces = (list) => {
      [markers, arcs].forEach((g) =>
        g.children.slice().forEach((c) => {
          c.geometry.dispose();
          c.material.dispose();
          g.remove(c);
        })
      );
      const max = Math.max(1, ...list.map((p) => p.value));
      state.markerData = [];
      list.forEach((p, i) => {
        // Exact city coordinates from IP geo when we have them
        const coord =
          typeof p.lat === "number" && typeof p.lon === "number"
            ? [p.lat, p.lon]
            : COUNTRY_COORDS[p.country || p.name];
        if (!coord) return;
        const pos = toVec(coord[0], coord[1], R * 1.01);
        const strength = Math.sqrt(p.value / max);

        const dot = new THREE.Mesh(
          new THREE.CircleGeometry(0.018 + strength * 0.03, 24),
          new THREE.MeshBasicMaterial({
            color: theme.marker,
            transparent: true,
            opacity: 0.95,
          })
        );
        dot.position.copy(pos);
        dot.lookAt(pos.clone().multiplyScalar(2));
        markers.add(dot);

        const ring = new THREE.Mesh(
          new THREE.RingGeometry(0.03, 0.036, 40),
          new THREE.MeshBasicMaterial({
            color: theme.marker,
            transparent: true,
            opacity: 0.6,
            side: THREE.DoubleSide,
            depthWrite: false,
          })
        );
        ring.position.copy(pos);
        ring.lookAt(pos.clone().multiplyScalar(2));
        ring.userData = { phase: i * 0.37, strength };
        markers.add(ring);

        state.markerData.push({ ...p, pos, coord });

        const nearHome =
          Math.abs(coord[0] - HOME[0]) < 4 && Math.abs(coord[1] - HOME[1]) < 4;
        if (!nearHome) {
          arcs.add(
            new THREE.Line(
              buildArc(coord, HOME),
              arcMaterial(theme.arc, i * 0.19)
            )
          );
        }
      });
    };

    const focusOn = (name) => {
      const marker = state.markerData.find(
        (m) => m.country === name || m.name === name
      );
      const coord = COUNTRY_COORDS[name] || marker?.coord;
      if (!coord) return;
      const f = facing(coord[0], coord[1]);
      // shortest way round
      const turn =
        ((((f.y - state.rotY) % (2 * Math.PI)) + 3 * Math.PI) % (2 * Math.PI)) -
        Math.PI;
      state.targetY = state.rotY + turn;
      state.targetX = f.x;
      state.idleAt = performance.now();
    };

    apiRef.current = { setPlaces, focusOn };

    /* ---- loop ---- */
    const clock = new THREE.Clock();
    const tmp = new THREE.Vector3();
    let frame;
    let lastTip = null;
    const tick = () => {
      frame = requestAnimationFrame(tick);
      if (!state.visible) return;
      const t = clock.getElapsedTime();
      const now = performance.now();

      if (state.targetY !== null) {
        state.rotY += (state.targetY - state.rotY) * 0.08;
        state.rotX += (state.targetX - state.rotX) * 0.08;
        if (Math.abs(state.targetY - state.rotY) < 0.002) state.targetY = null;
      } else if (!state.dragging) {
        state.velY *= 0.94;
        state.rotY += state.velY;
        if (!reduced && now - state.idleAt > 2500) state.rotY += 0.0012;
      }
      globe.rotation.set(state.rotX, state.rotY, 0);

      markers.children.forEach((m) => {
        if (!m.userData.strength && m.userData.strength !== 0) return;
        const k = (t * 0.6 + m.userData.phase) % 1;
        const s = 1 + k * (2.2 + m.userData.strength * 2);
        m.scale.set(s, s, s);
        m.material.opacity = (1 - k) * 0.7;
      });
      arcs.children.forEach((a) => {
        a.material.uniforms.uTime.value = t;
      });

      // hover: nearest front-facing marker within 16px
      let hit = null;
      if (state.pointer && !state.dragging) {
        const w = el.clientWidth;
        const h = el.clientHeight;
        let best = 16;
        globe.updateMatrixWorld();
        state.markerData.forEach((m) => {
          tmp.copy(m.pos).applyMatrix4(globe.matrixWorld);
          if (tmp.z < 0.1) return; // back side
          tmp.project(camera);
          const sx = ((tmp.x + 1) / 2) * w;
          const sy = ((1 - tmp.y) / 2) * h;
          const d = Math.hypot(sx - state.pointer.x, sy - state.pointer.y);
          if (d < best) {
            best = d;
            hit = {
              name: m.label || m.name,
              country: m.country || m.name,
              flag: m.flag,
              value: m.value,
              x: sx,
              y: sy,
            };
          }
        });
      }
      if ((hit && hit.name) !== (lastTip && lastTip.name)) {
        lastTip = hit;
        setTip(hit);
        onHover?.(hit ? hit.country : null);
      }
      el.style.cursor = hit ? "pointer" : state.dragging ? "grabbing" : "grab";

      renderer.render(scene, camera);
    };
    tick();

    return () => {
      cancelAnimationFrame(frame);
      cancelAnimationFrame(resizeFrame);
      ro.disconnect();
      io.disconnect();
      el.removeEventListener("pointerdown", onDown);
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerup", onUp);
      el.removeEventListener("pointercancel", onUp);
      el.removeEventListener("pointerleave", onLeave);
      scene.traverse((o) => {
        o.geometry?.dispose();
        o.material?.dispose();
      });
      renderer.dispose();
      mount.removeChild(el);
      apiRef.current = {};
    };
    // onHover is a stable setter from the parent
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode]);

  useEffect(() => {
    apiRef.current.setPlaces?.(places);
  }, [places, mode]);

  useEffect(() => {
    if (focus) apiRef.current.focusOn?.(focus);
  }, [focus]);

  return (
    <div className="bx-globe" ref={mountRef}>
      {tip && (
        <div className="bx-globe-tip" style={{ left: tip.x, top: tip.y }}>
          <span>
            {tip.flag} {tip.name}
          </span>
          <strong>{tip.value}</strong>
        </div>
      )}
    </div>
  );
};

export default Globe;
