/** Instant scroll — the site's smooth scroll-behavior swallows JS scrolls. */
const jumpTo = (el) => {
  if (!el) return;
  const root = document.documentElement;
  const prev = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  root.scrollTop = el.getBoundingClientRect().top + root.scrollTop - 100;
  root.style.scrollBehavior = prev;
};

const change = (current, previous) => {
  if (!previous) return current ? { up: true, value: null } : null;
  const d = ((current - previous) / previous) * 100;
  return { up: d >= 0, value: Math.abs(Math.round(d)) };
};

/** Last 7 days vs the 7 before, from a 30-day daily series. */
const weekTrend = (series) => {
  const sum = (a) => a.reduce((s, v) => s + v, 0);
  const cur = sum(series.slice(-7));
  const prev = sum(series.slice(-14, -7));
  if (!prev) return cur ? { direction: "up", value: 100 } : null;
  const d = ((cur - prev) / prev) * 100;
  return { direction: d >= 0 ? "up" : "down", value: Math.abs(Math.round(d)) };
};

