// Segmented control with a pill that slides to the active option
const SlideTabs = ({ options, value, onChange, label, size }) => {
  const wrap = useRef(null);
  const [pill, setPill] = useState(null);

  useLayoutEffect(() => {
    const measure = () => {
      const el = wrap.current?.querySelector('[aria-selected="true"]');
      if (el) setPill({ left: el.offsetLeft, width: el.offsetWidth });
    };
    measure();
    let frame = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    });
    if (wrap.current) ro.observe(wrap.current);
    return () => {
      cancelAnimationFrame(frame);
      ro.disconnect();
    };
  }, [value, options]);

  return (
    <div
      className={`bx-tabs ${size === "sm" ? "bx-tabs-sm" : ""}`}
      role="tablist"
      aria-label={label}
      ref={wrap}
    >
      {pill && (
        <span
          className="bx-tabs-pill"
          style={{ transform: `translateX(${pill.left}px)`, width: pill.width }}
        />
      )}
      {options.map(([key, text, count]) => (
        <button
          key={key}
          role="tab"
          aria-selected={value === key}
          onClick={() => onChange(key)}
        >
          {text}
          {count !== undefined && (
            <span className="bx-tabs-count">{count}</span>
          )}
        </button>
      ))}
    </div>
  );
};

const Badge = ({ delta, suffix }) => {
  if (!delta) return <span className="bx-badge flat">—</span>;
  const Icon = delta.up ? ArrowUpRight : ArrowDownRight;
  return (
    <span className={`bx-badge ${delta.up ? "up" : "down"}`}>
      <Icon size={12} strokeWidth={2.5} />
      {delta.value === null ? "new" : `${delta.value}%`}
      {suffix && <span className="bx-badge-suffix">{suffix}</span>}
    </span>
  );
};

