const TickStrip = ({ data, onHover }) => {
  const max = Math.max(1, ...data);
  return (
    <div className="bx-ticks" onMouseLeave={() => onHover(null)}>
      {data.map((v, i) => (
        <span
          key={i}
          className={v ? "" : "is-zero"}
          style={{ "--h": `${Math.max(v ? 14 : 8, (v / max) * 100)}%` }}
          onMouseEnter={() => onHover({ i, v })}
        />
      ))}
    </div>
  );
};

const Kpi = ({ icon: Icon, label, value, trend, spark, sub }) => {
  const [hover, setHover] = useState(null);
  const day = hover
    ? new Date(Date.now() - (spark.length - 1 - hover.i) * 86400000)
    : null;
  return (
    <Card className="bx-kpi">
      <div className="bx-kpi-top">
        <span className="bx-kpi-label">
          <Icon size={14} strokeWidth={2} />
          {label}
        </span>
        <Badge
          delta={trend && { up: trend.direction === "up", value: trend.value }}
        />
      </div>
      <div className="bx-kpi-value">
        <AnimatedNumber value={value} />
      </div>
      <div className="bx-kpi-sub">
        {hover ? (
          <>
            <strong>{hover.v}</strong>{" "}
            {day.toLocaleDateString(undefined, {
              month: "short",
              day: "numeric",
            })}
          </>
        ) : (
          sub
        )}
      </div>
      <TickStrip data={spark} onHover={setHover} />
    </Card>
  );
};

