const TrafficChart = ({ data, height = 250 }) => {
  const [wrapRef, width] = useElementWidth();
  const [hover, setHover] = useState(null);

  const pad = { top: 22, right: 40, bottom: 26, left: 6 };
  const innerW = Math.max(0, width - pad.left - pad.right);
  const innerH = height - pad.top - pad.bottom;
  const n = data.length;
  const ticks = niceTicks(Math.max(0, ...data.map((d) => d.value)));
  const max = ticks[ticks.length - 1];
  const x = (i) => pad.left + (n > 1 ? (i / (n - 1)) * innerW : innerW / 2);
  const y = (v) => pad.top + innerH * (1 - v / max);

  // Monotone-ish smoothing: cubic segments with horizontal tangents
  const line = data
    .map((d, i) => {
      if (!i) return `M${x(0)},${y(d.value)}`;
      const cx = (x(i - 1) + x(i)) / 2;
      return `C${cx},${y(data[i - 1].value)} ${cx},${y(d.value)} ${x(i)},${y(
        d.value
      )}`;
    })
    .join("");
  const area = `${line}L${x(n - 1)},${pad.top + innerH}L${x(0)},${
    pad.top + innerH
  }Z`;

  const peak = data.reduce(
    (best, d, i) => (d.value > (best?.value ?? -1) ? { ...d, i } : best),
    null
  );
  const labelEvery = n <= 12 ? 1 : Math.ceil(n / 7);
  const hovered = hover !== null ? data[hover] : null;
  const drawKey = `${n}-${data[0]?.key}`;

  const onMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const i = Math.round(
      ((e.clientX - rect.left - pad.left) / innerW) * (n - 1)
    );
    setHover(Math.min(n - 1, Math.max(0, i)));
  };

  return (
    <div className="bx-traffic" ref={wrapRef} style={{ height }}>
      {width > 0 && (
        <svg
          width={width}
          height={height}
          onMouseMove={onMove}
          onMouseLeave={() => setHover(null)}
          role="img"
          aria-label="Visits over time"
        >
          <defs>
            <linearGradient id="bx-stroke" x1="0" x2="1" y1="0" y2="0">
              <stop offset="0%" stopColor="var(--bx-c1)" />
              <stop offset="55%" stopColor="var(--bx-c2)" />
              <stop offset="100%" stopColor="var(--bx-c3)" />
            </linearGradient>
            <linearGradient id="bx-fill" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor="var(--bx-c2)" stopOpacity="0.28" />
              <stop offset="100%" stopColor="var(--bx-c2)" stopOpacity="0" />
            </linearGradient>
          </defs>
          {ticks.map((t) => (
            <g key={t}>
              <line
                x1={pad.left}
                x2={pad.left + innerW}
                y1={y(t)}
                y2={y(t)}
                className="bx-gridline"
              />
              <text
                x={width - 4}
                y={y(t) + 4}
                textAnchor="end"
                className="bx-axis"
              >
                {t}
              </text>
            </g>
          ))}
          {data.map((d, i) =>
            i % labelEvery === 0 || i === n - 1 ? (
              <text
                key={d.key}
                x={x(i)}
                y={height - 6}
                textAnchor={i === 0 ? "start" : i === n - 1 ? "end" : "middle"}
                className="bx-axis"
              >
                {d.label}
              </text>
            ) : null
          )}
          <g key={drawKey}>
            <path d={area} fill="url(#bx-fill)" className="bx-area-fill" />
            <path
              d={line}
              className="bx-area-line"
              stroke="url(#bx-stroke)"
              pathLength="1"
            />
          </g>
          {peak && peak.value > 0 && !hovered && (
            <g className="bx-peak">
              <circle cx={x(peak.i)} cy={y(peak.value)} r="3.5" />
              <text x={x(peak.i)} y={y(peak.value) - 10} textAnchor="middle">
                peak {peak.value}
              </text>
            </g>
          )}
          {hovered && (
            <g>
              <line
                x1={x(hover)}
                x2={x(hover)}
                y1={pad.top}
                y2={pad.top + innerH}
                className="bx-crosshair"
              />
              <circle
                cx={x(hover)}
                cy={y(hovered.value)}
                r="9"
                className="bx-dot-halo"
              />
              <circle
                cx={x(hover)}
                cy={y(hovered.value)}
                r="4.5"
                className="bx-dot"
              />
            </g>
          )}
        </svg>
      )}
      {hovered && (
        <div
          className="bx-tooltip"
          style={{
            left: Math.min(Math.max(x(hover), 70), width - 70),
            top: Math.max(y(hovered.value) - 14, 0),
          }}
        >
          <span>{bucketTitle(hovered.key)}</span>
          <strong>{hovered.value.toLocaleString()}</strong> visit
          {hovered.value === 1 ? "" : "s"}
        </div>
      )}
    </div>
  );
};

/* ------------------------------------------------------------------ */
/* Visitor mix ring                                                     */
/* ------------------------------------------------------------------ */

const MixRing = ({ data }) => {
  const [hover, setHover] = useState(null);
  const total = data.reduce((s, d) => s + d.value, 0);
  if (!total) return <EmptyState message="No visitor types yet" />;

  const r = 62;
  const C = 2 * Math.PI * r;
  const gap = data.length > 1 ? 5 : 0;
  let acc = 0;
  const segs = data.map((d) => {
    const len = (d.value / total) * C;
    const seg = { ...d, start: acc, len: Math.max(len - gap, 1.5) };
    acc += len;
    return seg;
  });
  const active = segs.find((s) => s.label === hover);

  return (
    <div className="bx-mix">
      <div className="bx-ring">
        <svg viewBox="0 0 160 160" onMouseLeave={() => setHover(null)}>
          <circle cx="80" cy="80" r={r} className="bx-ring-track" />
          {segs.map((s, i) => (
            <circle
              key={s.label}
              cx="80"
              cy="80"
              r={r}
              stroke={s.color}
              strokeDasharray={`${s.len} ${C}`}
              strokeDashoffset={-s.start}
              className={`bx-ring-seg ${
                hover && hover !== s.label ? "is-dim" : ""
              } ${hover === s.label ? "is-on" : ""}`}
              style={{ animationDelay: `${i * 90}ms` }}
              onMouseEnter={() => setHover(s.label)}
            />
          ))}
        </svg>
        <div className="bx-ring-center">
          <strong>
            {active ? active.value.toLocaleString() : total.toLocaleString()}
          </strong>
          <span>{active ? active.label : "visitors"}</span>
          {active && <em>{pct(active.value, total)}</em>}
        </div>
      </div>
      <ul className="bx-mix-legend">
        {segs.map((s) => (
          <li
            key={s.label}
            className={hover && hover !== s.label ? "is-dim" : ""}
            onMouseEnter={() => setHover(s.label)}
            onMouseLeave={() => setHover(null)}
          >
            <span className="bx-swatch" style={{ background: s.color }} />
            <span className="bx-mix-name">{s.label}</span>
            <span className="bx-num">{s.value}</span>
          </li>
        ))}
      </ul>
    </div>
  );
};

