/* Engagement flow                                                      */
/* ------------------------------------------------------------------ */

const Funnel = ({ stages }) => {
  const [wrapRef, width] = useElementWidth();
  const [hover, setHover] = useState(null);
  const height = 200;
  const total = stages[0]?.value || 0;
  if (!total) return <EmptyState message="No visitors yet" />;

  const n = stages.length;
  const colW = width / n;
  const mid = height / 2;
  // sqrt keeps the small stages visible without lying about order
  const h = (v) => Math.max(6, Math.sqrt(v / total) * (height - 24));
  const cx = (i) => colW * i + colW / 2;

  let top = `M0,${mid - h(stages[0].value) / 2}`;
  let bottom = "";
  stages.forEach((s, i) => {
    const y0 = mid - h(s.value) / 2;
    if (i === 0) top += `L${cx(0)},${y0}`;
    else {
      const p = mid - h(stages[i - 1].value) / 2;
      const m = (cx(i - 1) + cx(i)) / 2;
      top += `C${m},${p} ${m},${y0} ${cx(i)},${y0}`;
    }
  });
  top += `L${width},${mid - h(stages[n - 1].value) / 2}`;
  for (let i = n - 1; i >= 0; i--) {
    const y1 = mid + h(stages[i].value) / 2;
    if (i === n - 1) bottom += `L${width},${y1}L${cx(i)},${y1}`;
    else {
      const p = mid + h(stages[i + 1].value) / 2;
      const m = (cx(i + 1) + cx(i)) / 2;
      bottom += `C${m},${p} ${m},${y1} ${cx(i)},${y1}`;
    }
  }
  bottom += `L0,${mid + h(stages[0].value) / 2}Z`;

  return (
    <div
      className="bx-funnel"
      ref={wrapRef}
      onMouseLeave={() => setHover(null)}
    >
      {width > 0 && (
        <svg
          width={width}
          height={height}
          aria-hidden="true"
          onMouseMove={(e) => {
            const x = e.clientX - e.currentTarget.getBoundingClientRect().left;
            setHover(Math.min(n - 1, Math.max(0, Math.floor(x / colW))));
          }}
        >
          <defs>
            <linearGradient id="bx-funnel" x1="0" x2="1">
              <stop offset="0%" stopColor="var(--bx-c1)" stopOpacity="0.95" />
              <stop offset="55%" stopColor="var(--bx-c2)" stopOpacity="0.85" />
              <stop offset="100%" stopColor="var(--bx-c3)" stopOpacity="0.8" />
            </linearGradient>
            <linearGradient id="bx-funnel-sheen" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor="#fff" stopOpacity="0.18" />
              <stop offset="50%" stopColor="#fff" stopOpacity="0" />
            </linearGradient>
          </defs>
          <path
            d={top + bottom}
            fill="url(#bx-funnel)"
            className="bx-funnel-shape"
          />
          <path d={top + bottom} fill="url(#bx-funnel-sheen)" />
          {stages.map((s, i) =>
            i ? (
              <line
                key={s.label}
                x1={colW * i}
                x2={colW * i}
                y1={8}
                y2={height - 8}
                className="bx-funnel-div"
              />
            ) : null
          )}
          {hover !== null && (
            <rect
              x={colW * hover}
              y={0}
              width={colW}
              height={height}
              className="bx-funnel-hover"
            />
          )}
        </svg>
      )}
      <div className="bx-funnel-cols">
        {stages.map((s, i) => (
          <div
            key={s.label}
            className={`bx-funnel-col ${hover === i ? "is-on" : ""}`}
            onMouseEnter={() => setHover(i)}
          >
            <span className="bx-funnel-label">{s.label}</span>
            <strong className="bx-num">{s.value.toLocaleString()}</strong>
            <span className="bx-funnel-pct">
              {i === 0
                ? "all visitors"
                : hover === i && stages[i - 1].value
                ? `${pct(s.value, stages[i - 1].value)} of prev`
                : pct(s.value, total)}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

/* ------------------------------------------------------------------ */
/* Heatmap                                                              */
/* ------------------------------------------------------------------ */

const Heatmap = ({ data, busiest }) => {
  const [hover, setHover] = useState(null);
  const max = useMemo(() => Math.max(1, ...data.flat()), [data]);
  const hasData = data.some((row) => row.some((c) => c > 0));
  if (!hasData) return <EmptyState message="No visit times recorded yet" />;
  const shown = hover || busiest;

  return (
    <div className="bx-heat-wrap">
      <div className="bx-heat" onMouseLeave={() => setHover(null)}>
        {DAYS.map((day, d) => (
          <div key={day} className="bx-heat-row">
            <span className="bx-heat-day">{day}</span>
            {data[d].map((count, hr) => (
              <span
                key={hr}
                className={`bx-heat-cell ${
                  hover && hover.day === d && hover.hour === hr ? "is-on" : ""
                }`}
                style={{
                  "--i": count ? 0.12 + (count / max) * 0.88 : 0,
                  animationDelay: `${(d * 24 + hr) * 3}ms`,
                }}
                onMouseEnter={() => setHover({ day: d, hour: hr, count })}
              />
            ))}
          </div>
        ))}
        <div className="bx-heat-row bx-heat-hours">
          <span className="bx-heat-day" />
          {Array.from({ length: 24 }, (_, hr) => (
            <span key={hr}>{hr % 6 === 0 ? `${hr}:00` : ""}</span>
          ))}
        </div>
      </div>
      {shown && (
        <div className="bx-heat-readout">
          <span className="bx-note">{hover ? "Selected" : "Busiest slot"}</span>
          <strong>
            {DAYS[shown.day]} {String(shown.hour).padStart(2, "0")}:00
          </strong>
          <span className="bx-num">
            {shown.count} visit{shown.count === 1 ? "" : "s"}
          </span>
        </div>
      )}
    </div>
  );
};

