const CommandPalette = ({
  open,
  onClose,
  actions,
  visitors,
  onSelect,
  mode,
}) => {
  const [q, setQ] = useState("");
  const [idx, setIdx] = useState(0);
  const inputRef = useRef(null);

  useEffect(() => {
    if (open) {
      setQ("");
      setIdx(0);
      setTimeout(() => inputRef.current?.focus(), 20);
    }
  }, [open]);

  const items = useMemo(() => {
    const s = q.trim().toLowerCase();
    const acts = actions
      .filter((a) => !s || a.label.toLowerCase().includes(s))
      .map((a) => ({ ...a, kind: "action" }));
    const people = s
      ? visitors
          .filter(
            (v) =>
              v.visitorId?.toLowerCase().includes(s) ||
              v.email?.toLowerCase().includes(s) ||
              v.referralSource?.toLowerCase().includes(s) ||
              v.detectedType?.toLowerCase().includes(s)
          )
          .slice(0, 6)
          .map((v) => ({
            kind: "visitor",
            id: v.id,
            label: shortVisitorId(v),
            hint: `${typeMeta(v.detectedType).label} · ${
              v.totalVisits || 0
            } visits${v.email ? ` · ${v.email}` : ""}`,
            run: () => onSelect(v),
          }))
      : [];
    return [...acts, ...people];
  }, [q, actions, visitors, onSelect]);

  useEffect(() => setIdx(0), [q]);

  const run = (item) => {
    if (!item) return;
    onClose();
    item.run();
  };

  const onKey = (e) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setIdx((i) => Math.min(items.length - 1, i + 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setIdx((i) => Math.max(0, i - 1));
    } else if (e.key === "Enter") {
      e.preventDefault();
      run(items[idx]);
    } else if (e.key === "Escape") {
      onClose();
    }
  };

  // Portaled: a transformed ancestor would trap position:fixed
  return createPortal(
    <div className="ad-portal" data-mode={mode}>
      <AnimatePresence>
        {open && (
          <motion.div
            className="bx-cmd-backdrop"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          >
            <motion.div
              className="bx-cmd"
              role="dialog"
              aria-label="Command palette"
              initial={{ opacity: 0, scale: 0.96, y: -8 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.98 }}
              transition={{ type: "spring", stiffness: 420, damping: 32 }}
              onClick={(e) => e.stopPropagation()}
            >
              <label className="bx-cmd-input">
                <Search size={16} />
                <input
                  ref={inputRef}
                  value={q}
                  onChange={(e) => setQ(e.target.value)}
                  onKeyDown={onKey}
                  placeholder="Search visitors or jump to…"
                />
                <kbd>esc</kbd>
              </label>
              <ul className="bx-cmd-list">
                {items.length === 0 && (
                  <li className="bx-cmd-empty">No matches</li>
                )}
                {items.map((item, i) => (
                  <li
                    key={`${item.kind}-${item.id}`}
                    className={i === idx ? "is-on" : ""}
                    onMouseEnter={() => setIdx(i)}
                    onClick={() => run(item)}
                  >
                    <span className="bx-cmd-kind">
                      {item.kind === "visitor" ? "Visitor" : item.group}
                    </span>
                    <span className="bx-cmd-label">
                      {item.kind === "visitor" ? (
                        <code>{item.label}</code>
                      ) : (
                        item.label
                      )}
                    </span>
                    {item.hint && (
                      <span className="bx-cmd-hint">{item.hint}</span>
                    )}
                    {i === idx && (
                      <CornerDownLeft size={13} className="bx-cmd-enter" />
                    )}
                  </li>
                ))}
              </ul>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>,
    document.body
  );
};

