/* ------------------------------------------------------------------ */
/* Visitors table                                                      */
/* ------------------------------------------------------------------ */

/**
 * IDs look like `visitor_1764172662876_yjepuyqrb`. The random tail is the
 * distinctive part and fits a column; truncating the timestamp instead just
 * yields near-identical strings ending in a stray underscore.
 */
export const shortVisitorId = (visitor) => {
  const raw = visitor.visitorId || visitor.id || "";
  const parts = raw.replace(/^visitor_/, "").split("_");
  const tail = parts[parts.length - 1];
  return tail && tail.length >= 4 ? tail : raw.slice(0, 12) || "unknown";
};

export const SortHeader = ({ label, sortKey, sort, onSort, className }) => {
  const active = sort.key === sortKey;
  return (
    <th
      className={className}
      aria-sort={
        active ? (sort.dir === "asc" ? "ascending" : "descending") : "none"
      }
    >
      <button
        className={`ad-th ${active ? "is-active" : ""}`}
        onClick={() => onSort(sortKey)}
      >
        {label}
        <Icon
          d={active ? (sort.dir === "asc" ? ICONS.up : ICONS.down) : ICONS.sort}
          size={12}
        />
      </button>
    </th>
  );
};

export const VisitorRow = React.memo(({ visitor, onSelect }) => {
  const meta = typeMeta(visitor.detectedType);
  const place = placeOf(visitor);
  const online = isOnline(visitor);
  const visits = visitor.totalVisits || 0;
  const score = leadScore(visitor);
  const shortId = shortVisitorId(visitor);
  const open = () => onSelect(visitor);

  return (
    <tr
      className="ad-row"
      onClick={open}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          open();
        }
      }}
      tabIndex={0}
    >
      <td>
        <div className="ad-who">
          <span className="ad-avatar" style={{ "--c": meta.color }}>
            {shortId.slice(0, 2)}
            {online && <span className="ad-avatar-live" title="Online now" />}
          </span>
          <div className="ad-stack">
            <span className="ad-primary">
              <code>{shortId}</code>
              {visits === 1 && <span className="ad-tag">new</span>}
            </span>
            <span className="ad-secondary">
              <span className="ad-swatch" style={{ background: meta.color }} />
              {meta.label} · {place.flag} {placeLabel(place)}
              {online && visitor.currentPage
                ? ` · on ${visitor.currentPage}`
                : ""}
              {visitor.email ? ` · ${visitor.email}` : ""}
            </span>
          </div>
        </div>
      </td>
      <td className="ad-num-cell">{visits.toLocaleString()}</td>
      <td className="ad-num-cell ad-hide-sm">
        {formatDuration(visitor.totalTimeSpent)}
      </td>
      <td className="ad-hide-sm">
        <span
          className="ad-source"
          title={visitor.fullReferrer || visitor.referralSource}
        >
          {prettySource(visitor.referralSource)}
        </span>
      </td>
      <td>
        <span className="ad-primary-plain" title={formatDate(visitor.lastSeen)}>
          {online ? "Now" : timeAgo(visitor.lastSeen)}
        </span>
      </td>
      <td className="ad-right">
        <span
          className="ad-score"
          data-tier={score >= 60 ? "hot" : score >= 30 ? "warm" : "cold"}
        >
          <span className="ad-score-track">
            <span style={{ width: `${score}%` }} />
          </span>
          <span className="ad-num">{score}</span>
        </span>
      </td>
    </tr>
  );
});

// Visitor detail — a right-hand sheet
export const VisitorSheet = ({ visitor, onClose, mode }) => {
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const meta = typeMeta(visitor.detectedType);
  const place = placeOf(visitor);
  const score = leadScore(visitor);

  const rows = [
    ["Visitor ID", visitor.visitorId || visitor.id],
    [
      "Confidence",
      visitor.typeConfidence
        ? `${Math.round(visitor.typeConfidence * 100)}%`
        : "—",
    ],
    ["Source", visitor.referralSource || "direct"],
    ["Full referrer", visitor.fullReferrer || "—"],
    [
      "Location",
      `${place.flag} ${placeLabel(place)}${
        place.region && place.region !== place.city ? ` (${place.region})` : ""
      }${place.precise ? "" : " · from timezone"}`,
    ],
    ["Network", place.org || "—"],
    ["Device", deviceOf(visitor.userAgent)],
    ["Current page", visitor.currentPage || "—"],
    ["Landing page", visitor.landingPage || "—"],
    ["Timezone", visitor.timezone || "—"],
    ["Language", visitor.language || "—"],
    ["Screen", visitor.screenSize || "—"],
    [
      "Scroll depth",
      visitor.lastScrollDepth ? `${visitor.lastScrollDepth}%` : "—",
    ],
    ["First seen", formatDate(visitor.firstSeen)],
    ["Last seen", formatDate(visitor.lastSeen)],
    ["Email", visitor.email || "—"],
  ];

  const sections = visitor.sectionsViewed || [];
  const questions = visitor.aiQuestions || [];
  const actions = (visitor.events || []).slice(-8).reverse();
  const pageRows = Object.keys({
    ...(visitor.pageViews || {}),
    ...(visitor.pageTime || {}),
  })
    .map((key) => ({
      path: pathFromKey(key),
      views: visitor.pageViews?.[key] || 0,
      seconds: visitor.pageTime?.[key] || 0,
    }))
    .sort((a, b) => b.views - a.views || b.seconds - a.seconds);

  // Portaled to <body>: a transformed ancestor would otherwise trap
  // position:fixed inside the page column.
  return createPortal(
    <div className="ad-portal" data-mode={mode}>
      <div className="ad-sheet-backdrop" onClick={onClose}>
        <aside
          className="ad-sheet"
          onClick={(e) => e.stopPropagation()}
          role="dialog"
          aria-modal="true"
          aria-label="Visitor detail"
        >
          <header className="ad-sheet-head">
            <div>
              <span className="ad-eyebrow">
                <span
                  className="ad-swatch"
                  style={{ background: meta.color }}
                />
                {meta.label}
              </span>
              <h3>
                <code>{shortVisitorId(visitor)}</code>
              </h3>
            </div>
            <button
              className="ad-icon-btn"
              onClick={onClose}
              aria-label="Close"
            >
              <Icon d={ICONS.close} />
            </button>
          </header>

          <div className="ad-sheet-stats">
            <div>
              <span>Visits</span>
              <strong>{visitor.totalVisits || 0}</strong>
            </div>
            <div>
              <span>Time on site</span>
              <strong>{formatDuration(visitor.totalTimeSpent)}</strong>
            </div>
            <div>
              <span>Lead score</span>
              <strong>{score}</strong>
            </div>
          </div>

          <dl className="ad-sheet-list">
            {rows.map(([label, value]) => (
              <div key={label}>
                <dt>{label}</dt>
                <dd>{String(value)}</dd>
              </div>
            ))}
          </dl>

          {pageRows.length > 0 && (
            <div className="ad-sheet-block">
              <h4>Pages · {pageRows.length}</h4>
              <ul className="ad-pages">
                {pageRows.map((p) => (
                  <li key={p.path}>
                    <code>{p.path}</code>
                    <span>
                      {p.views} view{p.views === 1 ? "" : "s"}
                    </span>
                    <span>{formatDuration(p.seconds)}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {actions.length > 0 && (
            <div className="ad-sheet-block">
              <h4>Actions</h4>
              <ul className="ad-questions">
                {actions.map((a, i) => (
                  <li key={i}>
                    <span>
                      {{
                        resume: "Opened the résumé",
                        contact_submit: "Sent a contact message",
                        email_click: "Clicked the email link",
                        outbound: `Went to ${a.label}`,
                      }[a.type] || a.type}
                      {a.page ? ` · from ${a.page}` : ""}
                    </span>
                    <time>{formatDate(a.timestamp)}</time>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {sections.length > 0 && (
            <div className="ad-sheet-block">
              <h4>Sections viewed</h4>
              <div className="ad-chips">
                {sections.map((s) => (
                  <span key={s}>{s}</span>
                ))}
              </div>
            </div>
          )}

          {questions.length > 0 && (
            <div className="ad-sheet-block">
              <h4>AI questions · {questions.length}</h4>
              <ul className="ad-questions">
                {questions.slice(-8).map((q, i) => (
                  <li key={i}>
                    <span>{q.question}</span>
                    <time>
                      {formatDate(q.timestamp)}
                      {q.source ? ` · ${q.source}` : ""}
                      {q.page ? ` · ${q.page}` : ""}
                    </time>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {visitor.userAgent && (
            <div className="ad-sheet-block">
              <h4>User agent</h4>
              <code className="ad-ua">{visitor.userAgent}</code>
            </div>
          )}
        </aside>
      </div>
    </div>,
    document.body
  );
};

/* ------------------------------------------------------------------ */
/* Visitors table section (toolbar + table + pager)                     */
/* ------------------------------------------------------------------ */

export const VisitorsTable = ({
  visitors,
  filter,
  setFilter,
  filterCounts,
  searchTerm,
  setSearchTerm,
  searchRef,
  pageItems,
  sortedVisitors,
  sort,
  toggleSort,
  page,
  setPage,
  pageCount,
  onSelect,
  SegmentedControl = Segmented,
}) => (
  <>
    <div className="ad-table-section">
      <header className="ad-panel-head">
        <h2>All visitors</h2>
      </header>
      <div className="ad-toolbar">
        <SegmentedControl
          label="Filter visitors"
          value={filter}
          onChange={setFilter}
          options={FILTERS.map(([key, text]) => [key, text, filterCounts[key]])}
        />
        <label className="ad-search">
          <Icon d={ICONS.search} />
          <input
            ref={searchRef}
            type="text"
            placeholder="Search id, type, source, email"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          {searchTerm ? (
            <button
              className="ad-icon-btn"
              onClick={() => setSearchTerm("")}
              aria-label="Clear search"
            >
              <Icon d={ICONS.close} size={14} />
            </button>
          ) : (
            <kbd>/</kbd>
          )}
        </label>
      </div>

      {pageItems.length === 0 ? (
        <EmptyState
          message={
            visitors.length === 0
              ? "No visitors tracked yet — the collection is empty."
              : "No visitors match this filter."
          }
        />
      ) : (
        <div className="ad-table-wrap">
          <table className="ad-table">
            <thead>
              <tr>
                <SortHeader
                  label="Visitor"
                  sortKey="visitor"
                  sort={sort}
                  onSort={toggleSort}
                />
                <SortHeader
                  label="Visits"
                  sortKey="visits"
                  sort={sort}
                  onSort={toggleSort}
                  className="ad-num-cell"
                />
                <SortHeader
                  label="Time"
                  sortKey="time"
                  sort={sort}
                  onSort={toggleSort}
                  className="ad-num-cell ad-hide-sm"
                />
                <SortHeader
                  label="Source"
                  sortKey="source"
                  sort={sort}
                  onSort={toggleSort}
                  className="ad-hide-sm"
                />
                <SortHeader
                  label="Last seen"
                  sortKey="lastSeen"
                  sort={sort}
                  onSort={toggleSort}
                />
                <SortHeader
                  label="Score"
                  sortKey="score"
                  sort={sort}
                  onSort={toggleSort}
                  className="ad-right"
                />
              </tr>
            </thead>
            <tbody>
              {pageItems.map((visitor) => (
                <VisitorRow
                  key={visitor.id}
                  visitor={visitor}
                  onSelect={onSelect}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}

      <footer className="ad-pager">
        <span className="ad-muted">
          {sortedVisitors.length
            ? `${Math.min(page, pageCount - 1) * PAGE_SIZE + 1}–${
                Math.min(page, pageCount - 1) * PAGE_SIZE + pageItems.length
              } of ${sortedVisitors.length.toLocaleString()}`
            : "0 results"}
          {sortedVisitors.length !== visitors.length &&
            ` · ${visitors.length.toLocaleString()} total`}
        </span>
        {pageCount > 1 && (
          <div className="ad-pager-btns">
            <button
              className="ad-btn ad-btn-sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
            >
              Previous
            </button>
            <span className="ad-muted">
              {Math.min(page, pageCount - 1) + 1} / {pageCount}
            </span>
            <button
              className="ad-btn ad-btn-sm"
              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
              disabled={page >= pageCount - 1}
            >
              Next
            </button>
          </div>
        )}
      </footer>
    </div>
  </>
);
