import React, {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
} from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import { db } from "../../firebase/config";
import {
  collection,
  getDocs,
  onSnapshot,
  query,
  orderBy,
  limit,
} from "firebase/firestore";
import Header from "../../components/header/Header";
import Footer from "../../components/footer/Footer";
import {
  buildAnalytics,
  leadScore,
  placeOf,
  placeLabel,
  toDate,
  trafficSeries,
} from "../../services/analytics";
import {
  MAX_VISITORS,
  PAGE_SIZE,
  FILTERS,
  matchesFilter,
  prettySource,
  VisitorSheet,
} from "./parts";
import BentoView from "./bento/BentoView";
import "./AdminDashboard.css";

const AdminDashboard = ({ theme, setTheme }) => {
  const { isAdmin } = useAuth();
  const mode = theme?.name === "light" ? "light" : "dark";
  const [visitors, setVisitors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [filter, setFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [trafficRange, setTrafficRange] = useState("month");
  const [page, setPage] = useState(0);
  const [selectedVisitor, setSelectedVisitor] = useState(null);
  const [sort, setSort] = useState({ key: "lastSeen", dir: "desc" });
  const searchRef = useRef(null);

  const toggleSort = useCallback((key) => {
    setSort((prev) =>
      prev.key === key
        ? { key, dir: prev.dir === "desc" ? "asc" : "desc" }
        : { key, dir: "desc" }
    );
  }, []);

  // "/" jumps to search, like most dev dashboards
  useEffect(() => {
    const onKey = (e) => {
      const tag = e.target?.tagName;
      if (e.key === "/" && tag !== "INPUT" && tag !== "TEXTAREA") {
        e.preventDefault();
        searchRef.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  /* ---- Live data. One realtime listener beats polling the whole
         collection every 60s: Firestore only bills the changed docs. ---- */
  useEffect(() => {
    if (!isAdmin) {
      setLoading(false);
      return undefined;
    }

    let cancelled = false;
    const applyDocs = (docs) => {
      if (cancelled) return;
      setVisitors(docs);
      setLastUpdated(new Date());
      setError(null);
      setLoading(false);
    };

    const q = query(
      collection(db, "visitors"),
      orderBy("lastSeen", "desc"),
      limit(MAX_VISITORS)
    );

    const unsubscribe = onSnapshot(
      q,
      async (snapshot) => {
        const docs = snapshot.docs.map((d) => ({ id: d.id, ...d.data() }));
        // Docs written before `lastSeen` existed are invisible to an
        // orderBy query — fall back to an unordered read so they still show.
        if (docs.length === 0) {
          try {
            const fallback = await getDocs(collection(db, "visitors"));
            applyDocs(fallback.docs.map((d) => ({ id: d.id, ...d.data() })));
            return;
          } catch (err) {
            console.error("Visitor fallback fetch failed:", err);
          }
        }
        applyDocs(docs);
      },
      (err) => {
        console.error("Error streaming visitors:", err);
        if (cancelled) return;
        setError(err.message || "Could not load visitor data");
        setLoading(false);
      }
    );

    return () => {
      cancelled = true;
      unsubscribe();
    };
  }, [isAdmin]);

  const analytics = useMemo(() => buildAnalytics(visitors), [visitors]);

  const traffic = useMemo(() => trafficSeries(visitors, trafficRange), [
    visitors,
    trafficRange,
  ]);
  const trafficTotal = useMemo(() => traffic.reduce((s, b) => s + b.value, 0), [
    traffic,
  ]);

  // Same range, one period earlier — for the "vs previous" delta
  const trafficPrevTotal = useMemo(() => {
    const back = { week: 7, month: 30, year: 365 }[trafficRange];
    const then = new Date(Date.now() - back * 86400000);
    return trafficSeries(visitors, trafficRange, then).reduce(
      (s, b) => s + b.value,
      0
    );
  }, [visitors, trafficRange]);

  const filterCounts = useMemo(() => {
    const counts = {};
    FILTERS.forEach(([key]) => {
      counts[key] = visitors.filter((v) => matchesFilter(v, key)).length;
    });
    return counts;
  }, [visitors]);

  const filteredVisitors = useMemo(() => {
    const searchLower = searchTerm.trim().toLowerCase();
    return visitors.filter((visitor) => {
      if (!matchesFilter(visitor, filter)) return false;
      if (!searchLower) return true;
      return (
        visitor.visitorId?.toLowerCase().includes(searchLower) ||
        visitor.detectedType?.toLowerCase().includes(searchLower) ||
        visitor.referralSource?.toLowerCase().includes(searchLower) ||
        visitor.email?.toLowerCase().includes(searchLower) ||
        visitor.timezone?.toLowerCase().includes(searchLower)
      );
    });
  }, [visitors, filter, searchTerm]);

  const sortedVisitors = useMemo(() => {
    const value = (v) => {
      switch (sort.key) {
        case "visits":
          return v.totalVisits || 0;
        case "time":
          return v.totalTimeSpent || 0;
        case "score":
          return leadScore(v);
        case "source":
          return prettySource(v.referralSource);
        case "visitor":
          return v.detectedType || "unknown";
        case "lastSeen":
        default:
          return toDate(v.lastSeen)?.getTime() || 0;
      }
    };

    const factor = sort.dir === "asc" ? 1 : -1;
    return [...filteredVisitors].sort((a, b) => {
      const av = value(a);
      const bv = value(b);
      if (typeof av === "string" || typeof bv === "string") {
        return String(av).localeCompare(String(bv)) * factor;
      }
      return (av - bv) * factor;
    });
  }, [filteredVisitors, sort]);

  // Keep the pager in range when filters shrink the result set
  const pageCount = Math.max(1, Math.ceil(sortedVisitors.length / PAGE_SIZE));
  useEffect(() => {
    setPage(0);
  }, [filter, searchTerm, sort]);

  const pageItems = useMemo(() => {
    const start = Math.min(page, pageCount - 1) * PAGE_SIZE;
    return sortedVisitors.slice(start, start + PAGE_SIZE);
  }, [sortedVisitors, page, pageCount]);

  const exportToCSV = useCallback(() => {
    const headers = [
      "Visitor ID",
      "Type",
      "Total Visits",
      "Time Spent (s)",
      "First Seen",
      "Last Seen",
      "Source",
      "Location",
      "Language",
      "Lead Score",
      "Email",
    ];
    const escape = (value) => {
      const s = value === undefined || value === null ? "" : String(value);
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };

    // Export what's on screen: same filter, same sort order
    const rows = sortedVisitors.map((v) => [
      v.visitorId || v.id,
      v.detectedType || "unknown",
      v.totalVisits || 0,
      v.totalTimeSpent || 0,
      toDate(v.firstSeen)?.toISOString() || "",
      toDate(v.lastSeen)?.toISOString() || "",
      v.referralSource || "direct",
      placeLabel(placeOf(v)),
      v.language || "",
      leadScore(v),
      v.email || "",
    ]);

    const csvContent = [headers, ...rows]
      .map((row) => row.map(escape).join(","))
      .join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `visitors_${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  }, [sortedVisitors]);

  const shell = (children) => (
    <div
      className="ad-root"
      data-mode={mode}
      data-variant="bento"
      style={{ background: theme?.body }}
    >
      <Header theme={theme} setTheme={setTheme} />
      {children}
      <Footer theme={theme} />
    </div>
  );

  if (!isAdmin) {
    return shell(
      <main className="ad-page ad-center">
        <span className="ad-eyebrow">Restricted</span>
        <h1 className="ad-title">Admins only</h1>
        <p className="ad-subtitle">
          You don't have permission to view this page.
        </p>
        <Link to="/home" className="ad-btn">
          Back to home
        </Link>
      </main>
    );
  }

  if (loading) {
    return shell(
      <main className="ad-page" aria-busy="true">
        <div className="ad-skel ad-skel-title" />
        <div className="ad-kpis">
          {[0, 1, 2, 3, 4].map((i) => (
            <div key={i} className="ad-kpi">
              <div className="ad-skel ad-skel-line" />
              <div className="ad-skel ad-skel-num" />
            </div>
          ))}
        </div>
        <div className="ad-skel ad-skel-chart" />
      </main>
    );
  }

  const table = {
    visitors,
    filter,
    setFilter,
    filterCounts,
    searchTerm,
    setSearchTerm,
    searchRef,
    pageItems,
    sortedVisitors,
    sort,
    toggleSort,
    page,
    setPage,
    pageCount,
  };

  const viewProps = {
    visitors,
    analytics,
    lastUpdated,
    error,
    exportToCSV,
    traffic,
    trafficTotal,
    trafficPrevTotal,
    trafficRange,
    setTrafficRange,
    table,
    mode,
    onSelect: setSelectedVisitor,
  };

  return shell(
    <>
      <BentoView {...viewProps} />
      {selectedVisitor && (
        <VisitorSheet
          visitor={selectedVisitor}
          mode={mode}
          onClose={() => setSelectedVisitor(null)}
        />
      )}
    </>
  );
};

export default AdminDashboard;
