/**
 * 📊 ANALYTICS DERIVATION
 *
 * Pure functions that turn raw `visitors` docs (see visitorIntelligence.js)
 * into everything the admin dashboard draws. No randomness, no placeholders —
 * if a panel has nothing to show, it gets an empty series and says so.
 *
 * Shape of a visitor doc we rely on:
 *   firstSeen / lastSeen   Firestore Timestamp
 *   totalVisits            number
 *   totalTimeSpent         seconds
 *   detectedType           recruiter | developer | searcher | social | techie | direct | unknown
 *   referralSource         linkedin | github | search | ...
 *   timezone / language    IANA zone, BCP-47 tag
 *   leadScore              0-100
 *   sessions               [{ start: ISO string, referrer, userAgent }]
 *   aiQuestions            [{ question, timestamp: ISO string }]
 *   behaviorPatterns       [{ type, timestamp: ms }]
 */

export const ACTIVE_WINDOW_MS = 5 * 60 * 1000;

/* ---------------- type / colour metadata ---------------- */

// Colours are fixed per type (validated categorical order), never by rank,
// so "Recruiter" is the same orange in every chart and filter state.
export const TYPE_META = {
  direct: { label: "Direct", color: "#3987e5", icon: "🔗" },
  recruiter: { label: "Recruiter", color: "#eb6834", icon: "💼" },
  searcher: { label: "Searcher", color: "#1baf7a", icon: "🔍" },
  developer: { label: "Developer", color: "#eda100", icon: "💻" },
  social: { label: "Social", color: "#e87ba4", icon: "📣" },
  techie: { label: "Tech community", color: "#9085e9", icon: "🧪" },
  unknown: { label: "Unknown", color: "#8a8a84", icon: "🌐" },
};

export const typeMeta = (type) => TYPE_META[type] || TYPE_META.unknown;

/* ---------------- date helpers ---------------- */

/** Firestore Timestamp | ISO string | ms | Date -> Date | null */
export const toDate = (value) => {
  if (!value) return null;
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  if (typeof value.toDate === "function") {
    try {
      return value.toDate();
    } catch {
      return null;
    }
  }
  const d = new Date(value);
  return isNaN(d.getTime()) ? null : d;
};

const dayKey = (d) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate()
  ).padStart(2, "0")}`;

const monthKey = (d) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;

const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

export const timeAgo = (value, now = Date.now()) => {
  const date = toDate(value);
  if (!date) return "—";
  const seconds = Math.max(0, Math.floor((now - date.getTime()) / 1000));
  if (seconds < 60) return `${seconds}s ago`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
  return `${Math.floor(seconds / 86400)}d ago`;
};

export const formatDate = (value) => {
  const date = toDate(value);
  return date ? date.toLocaleString() : "—";
};

/** Historic docs stored unrounded scores (35.63333…), so clamp on read too. */
export const leadScore = (visitor) =>
  Math.round(Math.min(Math.max(visitor?.leadScore || 0, 0), 100));

export const formatDuration = (seconds) => {
  const s = Math.max(0, Math.round(seconds || 0));
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
};

/**
 * Every moment this visitor showed up. Prefers the `sessions` array (one entry
 * per visit); falls back to firstSeen/lastSeen for docs written before it, so
 * older records still land on the charts instead of vanishing.
 */
export const visitDates = (visitor) => {
  const dates = [];
  if (Array.isArray(visitor.sessions)) {
    visitor.sessions.forEach((s) => {
      const d = toDate(s?.start);
      if (d) dates.push(d);
    });
  }
  if (dates.length === 0) {
    const first = toDate(visitor.firstSeen);
    const last = toDate(visitor.lastSeen);
    if (first) dates.push(first);
    if (last && (!first || last.getTime() !== first.getTime()))
      dates.push(last);
  }
  return dates;
};

