const REGION_FLAG = {
  America: "🌎",
  Europe: "🇪🇺",
  Asia: "🌏",
  Africa: "🌍",
  Australia: "🇦🇺",
  Pacific: "🌏",
  Atlantic: "🌍",
  Indian: "🌏",
};

/** IANA timezone -> a human place label. Unknown zones degrade to the city. */
export const placeFromTimezone = (tz) => {
  if (!tz || typeof tz !== "string") return { name: "Unknown", flag: "🌐" };
  const known = ZONE_PLACE[tz];
  if (known) return { name: known[0], flag: known[1] };
  const [region, ...rest] = tz.split("/");
  const city = (rest[rest.length - 1] || region || "").replace(/_/g, " ");
  return { name: city || tz, flag: REGION_FLAG[region] || "🌐" };
};

/** "IN" -> 🇮🇳 */
const flagOf = (code) =>
  /^[A-Za-z]{2}$/.test(code || "")
    ? String.fromCodePoint(
        ...code
          .toUpperCase()
          .split("")
          .map((c) => 127397 + c.charCodeAt(0))
      )
    : "🌐";

/**
 * Best known location. IP geolocation (city, coordinates, network) when the
 * visitor has it; otherwise the country implied by their timezone.
 */
export const placeOf = (visitor) => {
  const g = visitor?.geo;
  if (g && g.country) {
    return {
      name: g.country,
      city: g.city || "",
      region: g.region || "",
      flag: flagOf(g.countryCode),
      lat: typeof g.lat === "number" ? g.lat : null,
      lon: typeof g.lon === "number" ? g.lon : null,
      org: g.org || "",
      precise: true,
    };
  }
  return { ...placeFromTimezone(visitor?.timezone), precise: false };
};

/** "Chennai, India" / "India" */
export const placeLabel = (place) =>
  place.city && place.city !== place.name
    ? `${place.city}, ${place.name}`
    : place.name;

/** Pages are stored under pageKey(path); turn a key back into a path. */
export const pathFromKey = (key) =>
  key === "home" ? "/" : `/${key.replace(/_/g, "/")}`;

/** Coarse device class from the user agent. */
export const deviceOf = (ua = "") => {
  if (/iPad|Tablet|PlayBook|Silk|(Android(?!.*Mobile))/i.test(ua))
    return "Tablet";
  if (/Mobi|iPhone|iPod|Android.*Mobile|BlackBerry|Opera Mini/i.test(ua))
    return "Mobile";
  if (/bot|crawl|spider|slurp|headless/i.test(ua)) return "Bot";
  return ua ? "Desktop" : "Unknown";
};

/* ---------------- series builders ---------------- */

const emptyBuckets = (now, range) => {
  const buckets = [];
  if (range === "year") {
    const base = new Date(now.getFullYear(), now.getMonth(), 1);
    for (let i = 11; i >= 0; i--) {
      const d = new Date(base.getFullYear(), base.getMonth() - i, 1);
      buckets.push({
        key: monthKey(d),
        label: d.toLocaleDateString(undefined, { month: "short" }),
        value: 0,
      });
    }
    return buckets;
  }
  const days = range === "month" ? 30 : 7;
  const base = startOfDay(now);
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(base.getFullYear(), base.getMonth(), base.getDate() - i);
    buckets.push({
      key: dayKey(d),
      label:
        days === 7
          ? d.toLocaleDateString(undefined, { weekday: "short" })
          : `${d.getDate()}`,
      value: 0,
    });
  }
  return buckets;
};

const PALETTE = [
  "#4f46e5",
  "#7c3aed",
  "#ec4899",
  "#4dabf7",
  "#00ff88",
  "#ffd43b",
  "#ff6b6b",
];

/** Visits per day (or month) over the requested range. */
export const trafficSeries = (visitors, range, now = new Date()) => {
  const buckets = emptyBuckets(now, range);
  const index = new Map(buckets.map((b, i) => [b.key, i]));
  const keyOf = range === "year" ? monthKey : dayKey;

  visitors.forEach((v) => {
    visitDates(v).forEach((d) => {
      const i = index.get(keyOf(d));
      if (i !== undefined) buckets[i].value += 1;
    });
  });

  return buckets.map((b, i) => ({ ...b, color: PALETTE[i % PALETTE.length] }));
};

/** Daily counts for the small stat-card sparklines. */
const dailyCounts = (dates, days, now) => {
  const buckets = emptyBuckets(now, days === 30 ? "month" : "week");
  const index = new Map(buckets.map((b, i) => [b.key, i]));
  dates.forEach((d) => {
    const i = index.get(dayKey(d));
    if (i !== undefined) buckets[i].value += 1;
  });
  return buckets.map((b) => b.value);
};

const pctChange = (current, previous) => {
  if (previous === 0) {
    if (current === 0) return null;
    return { direction: "up", value: 100 };
  }
  const delta = ((current - previous) / previous) * 100;
  return {
    direction: delta >= 0 ? "up" : "down",
    value: Math.abs(Math.round(delta)),
  };
};

/* ---------------- the one entry point ---------------- */

export const buildAnalytics = (visitors, now = new Date()) => {
  const nowMs = now.getTime();
  const weekAgo = nowMs - 7 * 86400000;
  const twoWeeksAgo = nowMs - 14 * 86400000;

  const stats = {
    total: visitors.length,
    new: 0,
    returning: 0,
    recruiters: 0,
    developers: 0,
  };

  // 7d vs previous 7d, counted per metric
  const win = {
    total: [0, 0],
    new: [0, 0],
    returning: [0, 0],
    recruiters: [0, 0],
    developers: [0, 0],
  };
  const sparkSource = {
    total: [],
    new: [],
    returning: [],
    recruiters: [],
    developers: [],
  };

  const typeCounts = new Map();
  const sourceCounts = new Map();
  const placeCounts = new Map();
  const languageCounts = new Map();
  const heatmap = Array.from({ length: 7 }, () => new Array(24).fill(0));
  const events = [];

  const pageStats = new Map(); // path -> { views, visitors, seconds }
  const landingCounts = new Map();
  const deviceCounts = new Map();
  const goals = {
    resume: 0,
    contact: 0,
    outbound: 0,
    email: 0,
    jarvis: 0,
    shared: 0,
  };
  const campaignCounts = new Map(); // "linkedin · project" -> visits
  const shareNetworks = new Map();
  const outboundHosts = new Map();
  const questions = [];
  const liveNow = [];

  let activeNow = 0;
  let totalTime = 0;
  let leadScoreSum = 0;
  let engaged = 0; // leadScore >= 50

  visitors.forEach((v) => {
    const visits = v.totalVisits || 0;
    const first = toDate(v.firstSeen);
    const last = toDate(v.lastSeen);
    const type = v.detectedType || "unknown";
    const dates = visitDates(v);

    if (visits === 1) stats.new += 1;
    if (visits > 1) stats.returning += 1;
    if (type === "recruiter") stats.recruiters += 1;
    if (type === "developer") stats.developers += 1;

    if (last && nowMs - last.getTime() < ACTIVE_WINDOW_MS) {
      activeNow += 1;
      liveNow.push(v);
    }

    /* pages: views + time per page, landing page, device */
    const views = v.pageViews || {};
    const times = v.pageTime || {};
    new Set([...Object.keys(views), ...Object.keys(times)]).forEach((key) => {
      const path = pathFromKey(key);
      const entry = pageStats.get(path) || {
        path,
        views: 0,
        visitors: 0,
        seconds: 0,
      };
      entry.views += views[key] || 0;
      entry.seconds += times[key] || 0;
      if (views[key]) entry.visitors += 1;
      pageStats.set(path, entry);
    });
    if (v.landingPage) {
      landingCounts.set(
        v.landingPage,
        (landingCounts.get(v.landingPage) || 0) + 1
      );
    }
    const device = deviceOf(v.userAgent);
    deviceCounts.set(device, (deviceCounts.get(device) || 0) + 1);

    /* goals */
    const counts = v.eventCounts || {};
    if (counts.resume) goals.resume += 1;
    if (counts.contact_submit || v.contacted) goals.contact += 1;
    if (counts.outbound) goals.outbound += counts.outbound;
    if (counts.share) goals.shared += 1;

    /* every tagged visit (first or returning) counts toward its campaign */
    (v.sessions || []).forEach((sess) => {
      const utm = sess?.utm;
      if (!utm?.source) return;
      const label = utm.campaign
        ? `${utm.source} · ${utm.campaign}`
        : utm.source;
      campaignCounts.set(label, (campaignCounts.get(label) || 0) + 1);
    });
    if (v.email) goals.email += 1;
    if ((v.aiQuestions || []).length) goals.jarvis += 1;
    (v.events || []).forEach((ev) => {
      if (ev?.type === "share" && ev.label) {
        const network = String(ev.label).split(":")[0];
        shareNetworks.set(network, (shareNetworks.get(network) || 0) + 1);
      }
      if (ev?.type === "outbound" && ev.label) {
        outboundHosts.set(ev.label, (outboundHosts.get(ev.label) || 0) + 1);
      }
    });
    (v.aiQuestions || []).forEach((q) => {
      const at = toDate(q?.timestamp);
      if (at && q.question) {
        questions.push({
          id: `${v.id}-${at.getTime()}`,
          visitor: v,
          question: String(q.question),
          source: q.source || "chat",
          page: q.page || "",
          at,
        });
      }
    });

    totalTime += v.totalTimeSpent || 0;
    leadScoreSum += v.leadScore || 0;
    if ((v.leadScore || 0) >= 50) engaged += 1;

    typeCounts.set(type, (typeCounts.get(type) || 0) + 1);

    const source = v.referralSource || "direct";
    sourceCounts.set(source, (sourceCounts.get(source) || 0) + 1);

    const place = placeOf(v);
    const placeEntry = placeCounts.get(place.name) || { ...place, value: 0 };
    placeEntry.value += 1;
    placeCounts.set(place.name, placeEntry);

    if (v.language) {
      const lang = String(v.language);
      languageCounts.set(lang, (languageCounts.get(lang) || 0) + 1);
    }

    // Session-level rollups: heatmap, sparklines, traffic windows
    dates.forEach((d) => {
      heatmap[d.getDay()][d.getHours()] += 1;
      sparkSource.total.push(d);
      const t = d.getTime();
      if (t >= weekAgo) win.total[0] += 1;
      else if (t >= twoWeeksAgo) win.total[1] += 1;
    });

    if (first) {
      const t = first.getTime();
      sparkSource.new.push(first);
      if (t >= weekAgo) win.new[0] += 1;
      else if (t >= twoWeeksAgo) win.new[1] += 1;

      if (type === "recruiter") {
        sparkSource.recruiters.push(first);
        if (t >= weekAgo) win.recruiters[0] += 1;
        else if (t >= twoWeeksAgo) win.recruiters[1] += 1;
      }
      if (type === "developer") {
        sparkSource.developers.push(first);
        if (t >= weekAgo) win.developers[0] += 1;
        else if (t >= twoWeeksAgo) win.developers[1] += 1;
      }
    }

    // A "returning" event = any visit after the first one
    dates.slice(1).forEach((d) => {
      sparkSource.returning.push(d);
      const t = d.getTime();
      if (t >= weekAgo) win.returning[0] += 1;
      else if (t >= twoWeeksAgo) win.returning[1] += 1;
    });

    /* --- event stream, built only from timestamps we actually stored --- */
    const shortId = (v.visitorId || v.id || "")
      .replace(/^visitor_/, "")
      .slice(0, 10);
    const meta = typeMeta(type);

    if (first) {
      events.push({
        id: `${v.id}-first`,
        at: first,
        level: "success",
        message: `New ${meta.label.toLowerCase()} ${shortId} via ${source}`,
      });
    }
    dates.slice(1).forEach((d, i) => {
      events.push({
        id: `${v.id}-visit-${i}`,
        at: d,
        level: "info",
        message: `Return visit #${i + 2} — ${shortId}`,
      });
    });
    (v.aiQuestions || []).forEach((q, i) => {
      const at = toDate(q?.timestamp);
      if (!at) return;
      const text = String(q.question || "").slice(0, 60);
      events.push({
        id: `${v.id}-ai-${i}`,
        at,
        level: "debug",
        message: `AI question from ${shortId}: "${text}"`,
      });
    });
    (v.events || []).forEach((ev, i) => {
      const at = toDate(ev?.timestamp);
      if (!at || !ev?.type) return;
      const label = {
        resume: `Opened the résumé — ${shortId}`,
        contact_submit: `Sent a contact message — ${shortId}`,
        email_click: `Clicked the email link — ${shortId}`,
        outbound: `Went to ${ev.label} — ${shortId}`,
        share: `Shared a page on ${
          String(ev.label).split(":")[0]
        } — ${shortId}`,
        cta_contact: `Clicked "Get in touch" on ${ev.label} — ${shortId}`,
      }[ev.type];
      if (!label) return;
      events.push({
        id: `${v.id}-ev-${i}`,
        at,
        level: ev.type === "outbound" ? "info" : "success",
        kind: ev.type,
        message: label,
      });
    });
    (v.behaviorPatterns || []).forEach((p, i) => {
      const at = toDate(p?.timestamp);
      if (!at || !p?.type) return;
      events.push({
        id: `${v.id}-bp-${i}`,
        at,
        level: "warning",
        message:
          p.type === "deep_scroll"
            ? `Deep scroll ${Math.round(p.depth || 0)}% — ${shortId}`
            : `${String(p.type).replace(/_/g, " ")} — ${shortId}`,
      });
    });
  });

  const sortDesc = (a, b) => b.value - a.value;

  const typeBreakdown = Array.from(typeCounts.entries())
    .map(([type, value]) => ({
      label: typeMeta(type).label,
      color: typeMeta(type).color,
      value,
    }))
    .sort(sortDesc);

  const sources = Array.from(sourceCounts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc)
    .slice(0, 6);

  const places = Array.from(placeCounts.values()).sort(sortDesc).slice(0, 6);

  const languages = Array.from(languageCounts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc)
    .slice(0, 4);

  events.sort((a, b) => b.at - a.at);
  questions.sort((a, b) => b.at - a.at);

  const pages = Array.from(pageStats.values()).sort(
    (a, b) => b.views - a.views
  );
  const landing = Array.from(landingCounts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc)
    .slice(0, 8);
  const devices = Array.from(deviceCounts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc);
  const campaigns = Array.from(campaignCounts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc)
    .slice(0, 8);
  const shares = Array.from(shareNetworks.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc);
  const outbound = Array.from(outboundHosts.entries())
    .map(([label, value]) => ({ label, value }))
    .sort(sortDesc)
    .slice(0, 6);

  // Busiest slot in the week, straight off the heatmap we just filled
  let busiest = null;
  heatmap.forEach((row, day) =>
    row.forEach((count, hour) => {
      if (count > 0 && (!busiest || count > busiest.count)) {
        busiest = { day, hour, count };
      }
    })
  );

  return {
    stats,
    activeNow,
    engaged,
    busiest,
    avgTimeSpent: visitors.length ? totalTime / visitors.length : 0,
    avgLeadScore: visitors.length
      ? Math.round(leadScoreSum / visitors.length)
      : 0,
    trends: {
      total: pctChange(win.total[0], win.total[1]),
      new: pctChange(win.new[0], win.new[1]),
      returning: pctChange(win.returning[0], win.returning[1]),
      recruiters: pctChange(win.recruiters[0], win.recruiters[1]),
      developers: pctChange(win.developers[0], win.developers[1]),
    },
    sparklines: {
      total: dailyCounts(sparkSource.total, 30, now),
      new: dailyCounts(sparkSource.new, 30, now),
      returning: dailyCounts(sparkSource.returning, 30, now),
      recruiters: dailyCounts(sparkSource.recruiters, 30, now),
      developers: dailyCounts(sparkSource.developers, 30, now),
    },
    typeBreakdown,
    sources,
    places,
    languages,
    heatmap,
    events: events.slice(0, 40),
    pages,
    landing,
    devices,
    goals,
    outbound,
    campaigns,
    shares,
    questions: questions.slice(0, 50),
    liveNow,
  };
};
